import React, { FormEvent, useEffect, useRef, useState } from 'react'
import ReactDOM from 'react-dom/client'
import { closestCenter, DndContext, DragEndEvent, PointerSensor, useDraggable, useDroppable, useSensor, useSensors } from '@dnd-kit/core'
import { arrayMove, SortableContext, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { AlertTriangle, ArrowLeft, BarChart3, Bell, BriefcaseBusiness, Bug, Building2, CalendarCheck, CalendarDays, ChartNoAxesCombined, Check, CheckCircle2, CheckSquare2, ChevronDown, ChevronUp, Circle, CircleHelp, Code2, Edit3, ExternalLink, Eye, EyeOff, FolderKanban, GraduationCap, GripVertical, HeartPulse, LayoutDashboard, Lightbulb, Link2, List, LogOut, Map as MapIcon, Megaphone, MessageSquare, MoreHorizontal, Palette, Paperclip, Plus, Rocket, Search, Send, Settings, ShoppingCart, SlidersHorizontal, Sparkles, Target, Trash2, Users, X, Zap, type LucideIcon } from 'lucide-react'
import { create } from 'zustand'
import type { AdvancedTaskFilter, AuthSession, AutomationActionType, AutomationRun, CustomFieldDefinition, CustomFieldType, DashboardReport, GlobalSearchResult, Goal, GoalStatus, Notification, Portfolio, PortfolioHealth, PortfolioOverview, Priority, ProjectAutomation, ProjectOption, SavedTaskFilter, SaveAutomationInput, SignInInput, SignUpInput, Status, Task, UpdateProjectInput, UpdateProjectSettingsInput, UpdateTaskInput, WorkspaceInvite, WorkspaceMember, WorkspaceRole, WorkspaceSnapshot } from '@orbitask/contracts'
